    Rec(int a, int b, long c) : a(a), b(b), c(c) {}
};

struct sortCond {
    bool operator()(const Pair& p1, const Pair& p2) const {
        return p1.a <= p2.a;
    }
};

struct modOperations {
    virtual int mod(int a, int b, int m) = 0;
};

struct ModAdd : public modOperations {
    int mod(int a, int b, int m) override {
        return ((a % m) + (b % m)) % m;
    }
};

struct ModSub : public modOperations {
    int mod(int a, int b, int m) override {
        return ((long long)a % m - (long long)b % m + m) % m;
    }
};

struct ModMul : public modOperations {
    int mod(int a, int b, int m) override {
        return ((long long)(a % m) * (b % m)) % m;
    }
};

struct ModDiv : public modOperations {
    int mod(int a, int b, int m) override {
        return modMul().mod(a, findBinaryExponentian(b, m - 1, m), m);
    }
};

int findBinaryExponentian(int a, int pow, int mod) {
    if (pow == 1) {
        return a;
    } else if (pow == 0) {
        return 1;
    } else {
        int retVal = findBinaryExponentian(a, pow / 2, mod);
        int val = (pow % 2 == 0) ? 1 : a;
        return ((long long)retVal * retVal) % mod * val % mod;
    }
}

int findPow(int a, int b, int mod) {
    if (b == 1) {
        return a % mod;
    } else if (b == 0) {
        return 1;
    } else {
        int res = findPow(a, b / 2, mod);
        return ((long long)res * res % mod) * (b % 2 == 1 ? a : 1) % mod;
    }
}

int bleft(int ele, int* sortedArr, int size) {
    int l = 0;
    int h = size - 1;
    int ans = -1;
    while (l <= h) {
        int mid = l + (h - l) / 2;
        if (sortedArr[mid] < ele) {
            ans = mid;
            l = mid + 1;
        } else {
            h = mid - 1;
        }
    }
    return ans;
}

int gcd(int a, int b) {
    int div = b;
    int rem = a % b;
    while (rem != 0) {
        int temp = rem;
        rem = div % rem;
        div = temp;
